node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Update the warranty: increment claim_count and set resolution
db.prepare(\"UPDATE warranties SET claim_count = claim_count + 1, resolution = ? WHERE warranty_id = 'WR-4A95C8'\")
  .run('Claim filed: Intermittent connectivity issues — mouse disconnects from laptop for a few seconds then reconnects. Issue started late August 2026. Resolution requested: replacement.');

// Verify the update
const updated = db.prepare(\"SELECT * FROM warranties WHERE warranty_id = 'WR-4A95C8'\").get();
console.log(JSON.stringify(updated, null, 2));
"
